/// Finds all duplicate elements in an array using O(1) extra space.
///
/// Uses the sign-marking technique: each value `v` in the array is used as an
/// index (via `abs(v)`). If the value at that index is already negative, `v`
/// is a duplicate. Otherwise, negate it to mark it as seen.
///
/// # Constraints
/// - All elements must be positive integers in the range `[1, n]` where `n`
///   is the array length.
///
/// # Returns
/// A `Vec<usize>` containing each duplicate value (in first-seen order).
pub fn disjoint_set(arr: &mut [usize]) -> Vec<usize> {
    let mut duplicates = Vec::new();

    for i in 0..arr.len() {
        let idx = arr[i].wrapping_sub(1); // map value v → index v-1

        if idx >= arr.len() {
            continue;
        }

        // Use the MSB (highest bit) as a "seen" flag by marking the value
        // at that index. Since usize values are positive and bounded by n,
        // setting the high bit won't collide with any real index.
        if arr[idx] > usize::MAX / 2 {
            // Already marked → arr[i] is a duplicate
            duplicates.push(arr[i]);
        } else {
            // Mark as seen by setting the high bit
            arr[idx] |= usize::MAX / 2 + 1;
        }
    }

    // Restore original values (clear high bits)
    for v in arr.iter_mut() {
        *v &= usize::MAX / 2;
    }

    duplicates
}

fn main() {
    let mut data = vec![4, 3, 2, 7, 8, 2, 3, 1];
    let dupes = disjoint_set(&mut data);
    println!("Duplicates: {:?}", dupes); // [2, 3]
    println!("Array restored: {:?}", data); // [4, 3, 2, 7, 8, 2, 3, 1]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_duplicates() {
        let mut arr = vec![4, 3, 2, 7, 8, 2, 3, 1];
        let dupes = disjoint_set(&mut arr);
        assert_eq!(dupes, vec![2, 3]);
        assert_eq!(arr, vec![4, 3, 2, 7, 8, 2, 3, 1]);
    }

    #[test]
    fn test_no_duplicates() {
        let mut arr = vec![1, 2, 3, 4, 5];
        let dupes = disjoint_set(&mut arr);
        assert!(dupes.is_empty());
        assert_eq!(arr, vec![1, 2, 3, 4, 5]);
    }

    #[test]
    fn test_all_same() {
        let mut arr = vec![2, 2, 2, 2];
        let dupes = disjoint_set(&mut arr);
        assert_eq!(dupes, vec![2, 2, 2]);
        assert_eq!(arr, vec![2, 2, 2, 2]);
    }

    #[test]
    fn test_two_elements_duplicate() {
        let mut arr = vec![1, 1];
        let dupes = disjoint_set(&mut arr);
        assert_eq!(dupes, vec![1]);
        assert_eq!(arr, vec![1, 1]);
    }

    #[test]
    fn test_single_element() {
        let mut arr = vec![1];
        let dupes = disjoint_set(&mut arr);
        assert!(dupes.is_empty());
        assert_eq!(arr, vec![1]);
    }

    #[test]
    fn test_empty_array() {
        let mut arr: Vec<usize> = vec![];
        let dupes = disjoint_set(&mut arr);
        assert!(dupes.is_empty());
    }

    #[test]
    fn test_multiple_different_duplicates() {
        let mut arr = vec![1, 2, 3, 1, 2, 3, 1];
        let dupes = disjoint_set(&mut arr);
        assert_eq!(dupes, vec![1, 2, 3, 1]);
        assert_eq!(arr, vec![1, 2, 3, 1, 2, 3, 1]);
    }

    #[test]
    fn test_adjacent_duplicates() {
        let mut arr = vec![1, 1, 2, 2, 3, 3];
        let dupes = disjoint_set(&mut arr);
        assert_eq!(dupes, vec![1, 2, 3]);
        assert_eq!(arr, vec![1, 1, 2, 2, 3, 3]);
    }

    #[test]
    fn test_value_equals_length() {
        let mut arr = vec![3, 1, 3, 3];
        let dupes = disjoint_set(&mut arr);
        assert_eq!(dupes, vec![3, 3]);
        assert_eq!(arr, vec![3, 1, 3, 3]);
    }

    #[test]
    fn test_large_array() {
        let n = 1000;
        let mut arr: Vec<usize> = (1..=n).collect();
        // Add duplicates of 1 and 500
        arr.push(1);
        arr.push(500);
        arr.sort(); // not required, just to spread them
        let mut arr2 = arr.clone();
        let dupes = disjoint_set(&mut arr2);
        assert_eq!(dupes, vec![1, 500]);
        assert_eq!(arr2, arr);
    }
}

/// Finds all duplicate elements in an array using O(1) extra space.
///
/// Uses the sign-marking technique: each value `v` is used as an index
/// (`abs(v) - 1`). If the element at that index is already negative, `v` is a
/// duplicate. Otherwise, negate it to mark it as seen.
///
/// # Constraints
/// - All elements must be positive integers in `[1, n]` where `n` is the array length.
///
/// # Returns
/// A `Vec<i64>` of duplicate values (in first-seen order). The array is
/// restored to its original state before returning.
pub fn disjoint_set(arr: &mut [i64]) -> Vec<i64> {
    let n = arr.len();
    let mut duplicates = Vec::new();

    for i in 0..n {
        let idx = (arr[i].unsigned_abs() as usize).wrapping_sub(1);
        if idx >= n {
            continue;
        }
        if arr[idx] < 0 {
            duplicates.push(arr[i].unsigned_abs() as i64);
        } else {
            arr[idx] = -arr[idx];
        }
    }

    // Restore original values
    for v in arr.iter_mut() {
        if *v < 0 {
            *v = -*v;
        }
    }

    duplicates
}

fn main() {
    let mut data = vec![4, 3, 2, 7, 8, 2, 3, 1];
    let dupes = disjoint_set(&mut data);
    println!("Duplicates: {:?}", dupes);       // [2, 3]
    println!("Array restored: {:?}", data);     // [4, 3, 2, 7, 8, 2, 3, 1]
}

